create or replace function public.aos_cia_assignment_plan_transition_admin_v1(p_token text,p_plan_id uuid,p_action text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare auth jsonb;uid uuid;p record;act text:=upper(coalesce(p_action,''));v_ctx jsonb;v_run jsonb;v_released integer:=0;
begin
 auth:=public.aos_cia_verify_admin_session_v1(p_token);if not coalesce((auth->>'ok')::boolean,false)then return jsonb_build_object('ok',false,'error','UNAUTHORIZED');end if;uid:=(auth->>'user_id')::uuid;
 select*into p from public.aos_cia_assignment_plans where id=p_plan_id for update;if p.id is null then return jsonb_build_object('ok',false,'error','PLAN_NOT_FOUND');end if;
 if act='ACTIVATE'then if p.state<>'DRAFT'then return jsonb_build_object('ok',false,'error','PLAN_NOT_DRAFT','state',p.state);end if;v_ctx:=public.aos_cia_activation_context_summary_v1(p.activation_id);if not coalesce((v_ctx->>'ok')::boolean,false)or coalesce(v_ctx->>'activation_state','')<>'ACTIVE'then return jsonb_build_object('ok',false,'error',coalesce(v_ctx->>'error','ACTIVATION_NOT_ACTIVE'));end if;begin update public.aos_cia_assignment_plans set state='ACTIVE',updated_by_user_id=uid,updated_at=clock_timestamp()where id=p_plan_id;v_run:=public.aos_cia_assignment_allocate_internal_v1(p_plan_id,'INITIAL',uid,'initial:'||p_plan_id::text);if not coalesce((v_run->>'ok')::boolean,false)then raise exception'INITIAL_ALLOCATION_FAILED:%',coalesce(v_run->>'error','UNKNOWN');end if;exception when others then return jsonb_build_object('ok',false,'error','ACTIVATION_FAILED','detail',sqlerrm);end;return jsonb_build_object('ok',true,'plan_id',p_plan_id,'state','ACTIVE','run',v_run);
 elsif act='PAUSE'then if p.state<>'ACTIVE'then return jsonb_build_object('ok',false,'error','PLAN_NOT_ACTIVE','state',p.state);end if;update public.aos_cia_assignment_plans set state='PAUSED',updated_by_user_id=uid,updated_at=clock_timestamp()where id=p_plan_id;return jsonb_build_object('ok',true,'plan_id',p_plan_id,'state','PAUSED');
 elsif act='RESUME'then if p.state<>'PAUSED'then return jsonb_build_object('ok',false,'error','PLAN_NOT_PAUSED','state',p.state);end if;v_ctx:=public.aos_cia_activation_context_summary_v1(p.activation_id);if not coalesce((v_ctx->>'ok')::boolean,false)or coalesce(v_ctx->>'activation_state','')<>'ACTIVE'then return jsonb_build_object('ok',false,'error',coalesce(v_ctx->>'error','ACTIVATION_NOT_ACTIVE'));end if;update public.aos_cia_assignment_plans set state='ACTIVE',updated_by_user_id=uid,updated_at=clock_timestamp()where id=p_plan_id;return jsonb_build_object('ok',true,'plan_id',p_plan_id,'state','ACTIVE');
 elsif act in('CLOSE','CANCEL')then if act='CLOSE'and p.state not in('ACTIVE','PAUSED')then return jsonb_build_object('ok',false,'error','PLAN_CANNOT_CLOSE','state',p.state);end if;if act='CANCEL'and p.state not in('DRAFT','ACTIVE','PAUSED')then return jsonb_build_object('ok',false,'error','PLAN_CANNOT_CANCEL','state',p.state);end if;update public.aos_cia_assignments set state='RELEASED',released_at=clock_timestamp(),terminal_reason=case when act='CLOSE'then'PLAN_CLOSED'else'PLAN_CANCELLED'end,updated_by_user_id=uid,updated_at=clock_timestamp()where plan_id=p_plan_id and state in('RESERVED','ASSIGNED','IN_PROGRESS');get diagnostics v_released=row_count;update public.aos_cia_assignment_plans set state=case when act='CLOSE'then'CLOSED'else'CANCELLED'end,updated_by_user_id=uid,updated_at=clock_timestamp()where id=p_plan_id;return jsonb_build_object('ok',true,'plan_id',p_plan_id,'state',case when act='CLOSE'then'CLOSED'else'CANCELLED'end,'released_active',v_released);
 else return jsonb_build_object('ok',false,'error','INVALID_ACTION');end if;
exception when others then return jsonb_build_object('ok',false,'error','PLAN_TRANSITION_FAILED','detail',sqlerrm);end$$;
create or replace function public.aos_cia_assignment_topup_admin_v1(p_token text,p_plan_id uuid,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=public as $$declare auth jsonb;uid uuid;p record;rec jsonb;run jsonb;begin auth:=public.aos_cia_verify_admin_session_v1(p_token);if not coalesce((auth->>'ok')::boolean,false)then return jsonb_build_object('ok',false,'error','UNAUTHORIZED');end if;uid:=(auth->>'user_id')::uuid;select*into p from public.aos_cia_assignment_plans where id=p_plan_id;if p.id is null then return jsonb_build_object('ok',false,'error','PLAN_NOT_FOUND');end if;if p.state<>'ACTIVE'then return jsonb_build_object('ok',false,'error','PLAN_NOT_ACTIVE','state',p.state);end if;if p.topup_policy='NONE'then return jsonb_build_object('ok',false,'error','TOPUP_DISABLED');end if;rec:=public.aos_cia_assignment_reconcile_internal_v1(p_plan_id,uid);run:=public.aos_cia_assignment_allocate_internal_v1(p_plan_id,'TOPUP',uid,p_idempotency_key);return jsonb_build_object('ok',coalesce((run->>'ok')::boolean,false),'reconcile',rec,'run',run);end$$;
create or replace function public.aos_cia_assignment_reconcile_admin_v1(p_token text,p_plan_id uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare auth jsonb;uid uuid;begin auth:=public.aos_cia_verify_admin_session_v1(p_token);if not coalesce((auth->>'ok')::boolean,false)then return jsonb_build_object('ok',false,'error','UNAUTHORIZED');end if;uid:=(auth->>'user_id')::uuid;return public.aos_cia_assignment_reconcile_internal_v1(p_plan_id,uid);end$$;
create or replace function public.aos_cia_assignment_action_admin_v1(p_token text,p_assignment_id uuid,p_action text,p_reason text default null)returns jsonb language plpgsql security definer set search_path=public as $$declare auth jsonb;uid uuid;begin auth:=public.aos_cia_verify_admin_session_v1(p_token);if not coalesce((auth->>'ok')::boolean,false)then return jsonb_build_object('ok',false,'error','UNAUTHORIZED');end if;uid:=(auth->>'user_id')::uuid;return public.aos_cia_assignment_lease_transition_internal_v1(p_assignment_id,p_action,uid,p_reason);end$$;
create or replace function public.aos_cia_assignment_advisors_v1()returns jsonb language sql stable set search_path=public as $$select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'name',u.nombre,'code',u.codigo_asesor,'area',u.area,'level',u.nivel_jerarquia,'panels',coalesce(u.paneles_acceso,'{}'::text[]))order by u.nombre),'[]'::jsonb)from public.aos_usuarios u where u.activo=true and lower(coalesce(u.rol,''))='asesor';$$;
create or replace function public.aos_cia_assignment_plan_list_v1(p_include_terminal boolean default true,p_limit integer default 50,p_offset integer default 0)returns jsonb language sql stable set search_path=public as $$with q as(select p.*,c.nombre activation_name,c.channel,c.mode,c.purpose,aud.nombre audience_name,(select count(*)from public.aos_cia_assignment_targets t where t.plan_id=p.id)target_count from public.aos_cia_assignment_plans p join public.aos_audiencia_activaciones a on a.id=p.activation_id join public.aos_audiencia_activacion_config c on c.activacion_id=p.activation_id join public.aos_audiencias aud on aud.id=a.audiencia_id where p_include_terminal or p.state not in('CLOSED','CANCELLED')order by p.created_at desc limit least(greatest(coalesce(p_limit,50),1),100)offset greatest(coalesce(p_offset,0),0))select jsonb_build_object('ok',true,'items',coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb))from q;$$;
create or replace function public.aos_cia_assignment_plan_summary_v1(p_plan_id uuid)returns jsonb language plpgsql stable set search_path=public as $$declare p record;ctx jsonb;cand integer:=0;counts jsonb;targets jsonb;source integer:=0;depl numeric:=0;begin select p0.*,c.nombre activation_name,c.channel,c.mode,c.purpose,aud.nombre audience_name into p from public.aos_cia_assignment_plans p0 join public.aos_audiencia_activaciones a on a.id=p0.activation_id join public.aos_audiencia_activacion_config c on c.activacion_id=p0.activation_id join public.aos_audiencias aud on aud.id=a.audiencia_id where p0.id=p_plan_id;if p.id is null then return jsonb_build_object('ok',false,'error','PLAN_NOT_FOUND');end if;ctx:=public.aos_cia_activation_context_summary_v1(p.activation_id);source:=case when coalesce((ctx->>'ok')::boolean,false)then coalesce((ctx->>'assignable_now')::integer,0)else 0 end;cand:=public.aos_cia_assignment_candidate_count_v1(p_plan_id);depl:=case when source>0 then round(((source-cand)::numeric/source)*100,2)else 0 end;select jsonb_build_object('total',count(*),'reserved',count(*)filter(where state='RESERVED'),'assigned',count(*)filter(where state='ASSIGNED'),'in_progress',count(*)filter(where state='IN_PROGRESS'),'completed',count(*)filter(where state='COMPLETED'),'released',count(*)filter(where state='RELEASED'),'expired',count(*)filter(where state='EXPIRED'),'active',count(*)filter(where state in('RESERVED','ASSIGNED','IN_PROGRESS')))into counts from public.aos_cia_assignments where plan_id=p_plan_id;select coalesce(jsonb_agg(jsonb_build_object('advisor_user_id',t.advisor_user_id,'name',u.nombre,'code',u.codigo_asesor,'priority',t.priority,'weight_percent',t.weight_percent,'fixed_quantity',t.fixed_quantity,'capacity_limit',t.capacity_limit,'active',(select count(*)from public.aos_cia_assignments x where x.plan_id=p_plan_id and x.advisor_user_id=t.advisor_user_id and x.state in('RESERVED','ASSIGNED','IN_PROGRESS')),'assigned',(select count(*)from public.aos_cia_assignments x where x.plan_id=p_plan_id and x.advisor_user_id=t.advisor_user_id and x.state='ASSIGNED'),'in_progress',(select count(*)from public.aos_cia_assignments x where x.plan_id=p_plan_id and x.advisor_user_id=t.advisor_user_id and x.state='IN_PROGRESS'),'completed',(select count(*)from public.aos_cia_assignments x where x.plan_id=p_plan_id and x.advisor_user_id=t.advisor_user_id and x.state='COMPLETED'))order by t.priority,t.advisor_user_id),'[]'::jsonb)into targets from public.aos_cia_assignment_targets t join public.aos_usuarios u on u.id=t.advisor_user_id where t.plan_id=p_plan_id;return jsonb_build_object('ok',true,'plan',to_jsonb(p),'context',ctx,'source_available_now',source,'candidate_remaining',cand,'depletion_pct',depl,'counts',counts,'targets',targets,'observed_at',statement_timestamp());end$$;
create or replace function public.aos_cia_assignment_list_v1(p_plan_id uuid,p_advisor_user_id uuid default null,p_state text default null,p_limit integer default 50,p_offset integer default 0)returns jsonb language sql stable set search_path=public as $$with q as(select x.id,x.plan_id,x.activation_id,x.contact_key,x.advisor_user_id,u.nombre advisor_name,u.codigo_asesor advisor_code,x.state,x.source_rank,x.assigned_at,x.must_start_before,x.expires_at,x.started_at,x.completed_at,x.released_at,x.expired_at,x.terminal_reason from public.aos_cia_assignments x join public.aos_usuarios u on u.id=x.advisor_user_id where x.plan_id=p_plan_id and(p_advisor_user_id is null or x.advisor_user_id=p_advisor_user_id)and(p_state is null or upper(x.state)=upper(p_state))order by x.assigned_at desc,x.id limit least(greatest(coalesce(p_limit,50),1),100)offset greatest(coalesce(p_offset,0),0))select jsonb_build_object('ok',true,'items',coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb))from q;$$;
create or replace function public.aos_cia_assignment_events_v1(p_plan_id uuid,p_limit integer default 100)returns jsonb language sql stable set search_path=public as $$select jsonb_build_object('ok',true,'items',coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb))from(select e.id,e.plan_id,e.assignment_id,e.event_type,e.actor_user_id,u.nombre actor_name,e.payload,e.occurred_at from public.aos_cia_assignment_events e left join public.aos_usuarios u on u.id=e.actor_user_id where e.plan_id=p_plan_id order by e.occurred_at desc,e.id desc limit least(greatest(coalesce(p_limit,100),1),200))q;$$;
create or replace function public.aos_cia_assignment_advisor_workload_v1()returns jsonb language sql stable set search_path=public as $$select jsonb_build_object('ok',true,'items',coalesce(jsonb_agg(to_jsonb(q)order by q.active desc,q.advisor_name),'[]'::jsonb),'observed_at',statement_timestamp())from(select u.id advisor_user_id,u.nombre advisor_name,u.codigo_asesor advisor_code,u.area,count(x.id)filter(where x.state in('RESERVED','ASSIGNED','IN_PROGRESS'))::integer active,count(x.id)filter(where x.state='ASSIGNED')::integer assigned,count(x.id)filter(where x.state='IN_PROGRESS')::integer in_progress,count(x.id)filter(where x.state='COMPLETED')::integer completed,count(x.id)filter(where x.state='RELEASED')::integer released,count(x.id)filter(where x.state='EXPIRED')::integer expired,count(distinct x.plan_id)filter(where x.state in('RESERVED','ASSIGNED','IN_PROGRESS'))::integer active_plans,count(x.id)filter(where x.state='ASSIGNED'and x.must_start_before<=clock_timestamp())::integer overdue_to_start,count(x.id)filter(where x.state in('ASSIGNED','IN_PROGRESS')and x.expires_at<=clock_timestamp()+interval'60 minutes')::integer expiring_60m,min(x.assigned_at)filter(where x.state in('RESERVED','ASSIGNED','IN_PROGRESS'))oldest_active_at from public.aos_usuarios u left join public.aos_cia_assignments x on x.advisor_user_id=u.id where u.activo=true and lower(coalesce(u.rol,''))='asesor'group by u.id,u.nombre,u.codigo_asesor,u.area)q;$$;
revoke all on function public.aos_cia_assignment_plan_transition_admin_v1(text,uuid,text) from public,anon,authenticated;revoke all on function public.aos_cia_assignment_topup_admin_v1(text,uuid,text) from public,anon,authenticated;revoke all on function public.aos_cia_assignment_reconcile_admin_v1(text,uuid) from public,anon,authenticated;revoke all on function public.aos_cia_assignment_action_admin_v1(text,uuid,text,text) from public,anon,authenticated;revoke all on function public.aos_cia_assignment_advisors_v1() from public,anon,authenticated;revoke all on function public.aos_cia_assignment_plan_list_v1(boolean,integer,integer) from public,anon,authenticated;revoke all on function public.aos_cia_assignment_plan_summary_v1(uuid) from public,anon,authenticated;revoke all on function public.aos_cia_assignment_list_v1(uuid,uuid,text,integer,integer) from public,anon,authenticated;revoke all on function public.aos_cia_assignment_events_v1(uuid,integer) from public,anon,authenticated;revoke all on function public.aos_cia_assignment_advisor_workload_v1() from public,anon,authenticated;
